/* ── EFFETS DE SORT AUTOUR DU HÉROS ──────────────────────────────────────
   Un seul point d'entrée, appelé par les deux rendus du héros. Chaque effet
   est purement décoratif : aucun ne modifie l'état du jeu. */
function effetsHeros(sx,sy){
  // Tempête de Givre : onde qui s'élargit, épaisseur qui s'affine
  if(player.tempest>0){
    const k=1-player.tempest/0.4;
    ctx.save();
    ctx.strokeStyle='rgba(127,208,255,'+(player.tempest*2.2)+')';ctx.lineWidth=4*(1-k)+1;
    ctx.beginPath();ctx.arc(sx,sy,150*k,0,6.28);ctx.stroke();
    ctx.strokeStyle='rgba(223,242,255,'+(player.tempest*1.2)+')';ctx.lineWidth=1.5;
    ctx.beginPath();ctx.arc(sx,sy,150*k*0.82,0,6.28);ctx.stroke();
    ctx.restore();
  }
  // Cri de Guerre : onde dorée
  if(player.cri){
    const k=player.cri.t/player.cri.life, a=1-k;
    ctx.save();
    ctx.strokeStyle='rgba(244,211,94,'+(a*0.85)+')';ctx.lineWidth=5*a+1;
    ctx.beginPath();ctx.arc(sx,sy,player.cri.r*k,0,6.28);ctx.stroke();
    ctx.strokeStyle='rgba(255,242,192,'+(a*0.5)+')';ctx.lineWidth=2;
    ctx.beginPath();ctx.arc(sx,sy,player.cri.r*k*0.7,0,6.28);ctx.stroke();
    ctx.restore();
  }
  // Aura tant que le buff dure : on doit voir qu'on est galvanisé
  if(player.buffT>0){
    const p=0.5+0.5*Math.sin(performance.now()/180);
    const col=player.buffType==='power'?'244,211,94':'127,208,255';
    ctx.save();
    ctx.strokeStyle='rgba('+col+','+(0.28+0.22*p)+')';ctx.lineWidth=2;
    ctx.beginPath();ctx.ellipse(sx,sy+4,26+2*p,11+1*p,0,0,6.28);ctx.stroke();
    ctx.globalAlpha=0.10+0.08*p;ctx.fillStyle='rgb('+col+')';
    ctx.beginPath();ctx.ellipse(sx,sy-18,22,30,0,0,6.28);ctx.fill();
    ctx.restore();
  }
  // Moulinet : arc de crosse qui balaie 360°
  if(player.moulinet){
    const M=player.moulinet,k=M.t/M.life,a=1-k;
    const d0=M.ang+k*6.283*(M.salves||1), largeur=1.5;   /* un tour par salve */
    ctx.save();
    ctx.globalAlpha=0.85*a;
    ctx.strokeStyle='#ffd27f';ctx.lineWidth=7*a+1.5;ctx.lineCap='round';
    /* Ellipse, pas cercle : on est en vue isométrique, un cercle parfait
       flotterait au-dessus du sol au lieu d'y être posé. */
    ctx.beginPath();ctx.ellipse(sx,sy,M.r*0.78,M.r*0.39,0,d0-largeur,d0);ctx.stroke();
    ctx.globalAlpha=0.45*a;ctx.strokeStyle='#fff2c0';ctx.lineWidth=2.5;
    ctx.beginPath();ctx.ellipse(sx,sy,M.r*0.78,M.r*0.39,0,d0-largeur*0.6,d0);ctx.stroke();
    ctx.restore();
  }
}
/* Images rémanentes de la Charge. Dessinées AVANT le héros, dans renderIso. */
function dessinerFantomes(){
  if(!fantomes.length)return;
  const anim='Idle', img=HERO_IMG[anim];
  for(const f of fantomes){
    const s=isoPx(f.x,f.y), a=(1-f.t/f.life)*0.5;
    ctx.save();ctx.globalAlpha=a;
    if(img&&img.complete&&img.naturalWidth){
      const S=128,DRAW=128;
      ctx.imageSmoothingEnabled=false;
      const ty=hautSprite(s.y,DRAW,img,S,S,'h:'+anim);
      ctx.drawImage(img,0,(f.dir||0)*S,S,S,s.x-DRAW/2,ty,DRAW,DRAW);
      ctx.globalCompositeOperation='lighter';ctx.globalAlpha=a*0.6;
      ctx.drawImage(img,0,(f.dir||0)*S,S,S,s.x-DRAW/2,ty,DRAW,DRAW);
    } else {
      ctx.fillStyle='#8fdcff';ctx.fillRect(s.x-10,s.y-38,20,42);
    }
    ctx.restore();
  }
}
function drawPlayerVector(){
  const sx=player.x-cam.x,sy=player.y-cam.y;
  ctx.save();ctx.translate(sx,sy);ctx.scale(player.face,1);
  ctx.fillStyle='rgba(30,60,120,0.5)';
  for(const s of[-1,1]){ctx.beginPath();ctx.moveTo(0,-6);
    ctx.quadraticCurveTo(s*36,-30,s*42,-6);ctx.quadraticCurveTo(s*30,-2,s*26,8);
    ctx.quadraticCurveTo(s*20,-2,0,-6);ctx.fill();}
  ctx.strokeStyle='rgba(94,200,255,'+(0.5+0.3*Math.sin(performance.now()/150))+')';ctx.lineWidth=2;
  for(const s of[-1,1]){ctx.beginPath();ctx.moveTo(s*18,-12);ctx.lineTo(s*40,-8);ctx.stroke();}ctx.lineWidth=1;
  ctx.fillStyle='rgba(0,0,0,0.4)';ctx.beginPath();ctx.ellipse(0,player.r,13,5,0,0,6.28);ctx.fill();
  const hurt=player.hurt>0;
  ctx.fillStyle=hurt?'#7a3030':'#2b3348';ctx.beginPath();ctx.moveTo(-10,-4);ctx.lineTo(10,-4);ctx.lineTo(8,15);ctx.lineTo(-8,15);ctx.closePath();ctx.fill();
  ctx.fillStyle=hurt?'#8a3838':'#39415c';ctx.fillRect(-10,-6,20,6);
  ctx.fillStyle='#1b2233';ctx.fillRect(-7,15,5,9);ctx.fillRect(3,15,5,9);
  ctx.fillStyle='#5ec8ff';ctx.fillRect(-8,23,7,3);ctx.fillRect(2,23,7,3);
  ctx.fillStyle='#c9b28a';ctx.beginPath();ctx.arc(0,-11,6,0,6.28);ctx.fill();
  ctx.fillStyle='#241a12';ctx.fillRect(-6,-18,12,5);
  ctx.fillStyle='#0e1a10';ctx.fillRect(-5,-8,10,3);
  ctx.fillStyle='#8fe3ff';ctx.shadowBlur=8;ctx.shadowColor='#5ec8ff';
  ctx.fillRect(-4,-12,3,2);ctx.fillRect(1,-12,3,2);ctx.shadowBlur=0;
  const sw=player.swing>0?-0.6+(0.14-player.swing)/0.14*1.2:0.3;
  ctx.save();ctx.translate(9,2);ctx.rotate(sw);
  ctx.strokeStyle='#c9a06a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(22,9);ctx.stroke();
  ctx.strokeStyle='#1a1a1a';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(22,9);ctx.lineTo(31,9);ctx.stroke();ctx.lineWidth=1;ctx.restore();
  ctx.restore();
  effetsHeros(sx,sy);
}

/* ── ANCRAGE AU SOL ───────────────────────────────────────────────────────
   Toutes les planches étaient dessinées en supposant que le dessin descend
   jusqu'à 74 % de la case. Mesuré : c'est vrai pour le héros (74,0 %) et le
   diablotin (74,5 %), mais le golem s'arrête à 70,9 % et les boss descendent
   jusqu'à 98 %. Résultat, le golem flottait de 7 px et le Séraphin était
   enfoncé de 35 px sous son ombre.

   On ne suppose plus : on LIT le bas réel du dessin dans la première case,
   une seule fois par planche, et on cale les pieds sur l'ombre. Toute planche
   ajoutée plus tard se corrige donc toute seule. */
const _fracSol={}, _fracSolAverti={};
function fractionSol(im,cw,ch,cle){
  if(_fracSol[cle]!=null)return _fracSol[cle];
  /* ⚠ LA TABLE D'ABORD, ET C'EST TOUT L'INTÉRÊT.                   (v9.37)

     `getImageData` LÈVE une exception sur un canevas teinté, ce qui arrivera
     dès que les planches seront des fichiers séparés au lieu de `data:` URL.
     L'échec est silencieux : on retombe sur 0,74 pour TOUT le monde. Or
     mesuré au build sur les 350 planches du jeu, **168 s'écartent de plus de
     0,15 de cette valeur** — près d'un sprite sur deux serait enfoncé dans le
     sol ou flottant au-dessus.

     La mesure est donc faite à la construction (`_outils/generer_frac_sol.js`,
     décodeur PNG sans dépendance). Le chemin ci-dessous ne sert plus qu'aux
     planches ajoutées sans régénérer la table — il reste, mais il ne doit
     plus rien porter. */
  if(typeof FRAC_SOL!=='undefined'&&FRAC_SOL[cle]!=null){
    _fracSol[cle]=FRAC_SOL[cle];
    return _fracSol[cle];
  }
  /* ⚠ IL N'Y A PLUS DE CHEMIN DE SECOURS PAR LE CANEVAS, ET C'EST VOULU.

     Il en existait un, qui lisait les pixels par `getImageData`. Deux raisons
     de l'avoir retiré plutôt que gardé « au cas où » :

     — il ne fonctionnera plus. Dès que les planches seront des fichiers, le
       canevas sera teinté et l'appel lèvera une exception ;
     — il masquait le vrai problème. Une planche absente de la table retombait
       sur 0,74 en silence, alors que 168 des 350 planches s'en écartent de
       plus de 0,15. Un sprite mal calé ne se voit pas dans un test.

     Une planche manquante doit donc SE DIRE. On avertit une fois, et on rend
     l'ancien réglage pour ne pas rendre le jeu injouable pendant qu'on
     régénère la table. */
  if(!_fracSolAverti[cle]){
    _fracSolAverti[cle]=true;
    if(typeof console!=='undefined'&&console.warn)
      console.warn('fractionSol : planche « '+cle+' » absente de FRAC_SOL — '
        +'régénérer avec _outils/generer_frac_sol.js');
  }
  _fracSol[cle]=0.74;
  return _fracSol[cle];
}
/* `fractionOpaque` figurait ici — « part de pixels opaques d'une image, pour
   savoir si une planche est un objet découpé ou un bloc plein ». Elle était
   exportée mais **appelée nulle part** : du code mort, et un troisième
   `getImageData` qui aurait cassé au passage en fichiers séparés. Retirée en
   v9.37 plutôt que portée. */
/* Position du HAUT de la case pour que les pieds tombent sur l'ombre. */
function hautSprite(sy,DR,im,cw,ch,cle,ombreY){
  return sy+DR*(ombreY==null?0.02:ombreY)-fractionSol(im,cw,ch,cle)*DR;
}
/* ================================================================
   LA TEINTE D'UN SPRITE, PAR COMPOSITION                     (v9.55)

   Une variante élémentaire, c'est le même sprite d'une autre couleur : le
   jeu porte 160 planches d'ennemis, il n'en produira pas une de plus.

   ⚠ PAS `ctx.filter`. C'est la façon évidente — et elle ÉCHOUE EN SILENCE
   sur le socle : le filtre Canvas2D n'est arrivé dans Safari qu'en 16.4,
   quand le socle du projet est iOS 13. La propriété n'y lève rien, elle est
   simplement IGNORÉE : le sprite sort à sa couleur d'origine, toutes les
   variantes se ressemblent, et ça ne se voit que sur l'appareil — jamais
   dans la batterie, jamais sur PC. `test_compat.js` monte la garde depuis
   la v9.54.

   ⚠ PAS DE PRÉ-TEINTURE NON PLUS. Mesuré en lisant l'en-tête PNG des 160
   planches : 20,0 Mio décodés, 0,134 Mio par planche. Teindre tout d'avance
   pour quatre variantes coûterait +80 Mio sur les 89,8 du jeu. On teint donc
   LA CASE RÉELLEMENT DESSINÉE, dans un canevas UNIQUE réutilisé d'un ennemi
   à l'autre : la mémoire ne bouge pas.
   ================================================================ */
const TEINTE_COULEUR=0.72;   /* combien la couleur mange le sprite      */
const TEINTE_LUEUR=0.20;     /* ce qu'on lui rend en clarté ensuite     */

/* Le canevas de teinture. UN SEUL pour tout le jeu : un canevas par image,
   ce seraient soixante allocations par seconde. */
let _teintureCv=null,_teintureCtx=null;
function _teinturier(w,h){
  if(!_teintureCv){
    if(typeof document==='undefined'||!document.createElement)return null;
    _teintureCv=document.createElement('canvas');
    _teintureCtx=_teintureCv.getContext('2d');
    if(!_teintureCtx)return null;
  }
  /* Changer `width` VIDE le canevas — c'est la façon la plus rapide de le
     nettoyer. Quand la taille ne change pas, il faut effacer à la main. */
  if(_teintureCv.width!==w||_teintureCv.height!==h){_teintureCv.width=w;_teintureCv.height=h;}
  else _teintureCtx.clearRect(0,0,w,h);
  return _teintureCtx;
}

/* Une case de planche, teintée. Rend le canevas de travail — à dessiner tout
   de suite : le suivant l'écrasera. */
function teinterCase(im,sx,sy,sw,sh,rgb){
  if(!im||!rgb)return null;
  const w=Math.max(1,Math.round(sw)),h=Math.max(1,Math.round(sh));
  const g=_teinturier(w,h); if(!g)return null;
  const col='rgb('+rgb+')';
  g.imageSmoothingEnabled=false;
  g.globalCompositeOperation='source-over';
  g.globalAlpha=1;
  g.drawImage(im,sx,sy,sw,sh,0,0,w,h);
  /* `multiply` colore, mais il ne fait qu'ASSOMBRIR : un diablotin rouge
     teinté en vert deviendrait noir. La passe `lighter` lui rend sa clarté,
     sans quoi les variantes sombres sont illisibles sur un sol sombre. */
  g.globalCompositeOperation='multiply';
  g.globalAlpha=TEINTE_COULEUR;
  g.fillStyle=col;
  g.fillRect(0,0,w,h);
  g.globalCompositeOperation='lighter';
  g.globalAlpha=TEINTE_LUEUR;
  g.fillRect(0,0,w,h);
  /* ⚠ CE DÉCOUPAGE EST OBLIGATOIRE, ET IL VIENT EN DERNIER.
     Les deux passes précédentes ont peint le rectangle ENTIER, fond
     transparent compris. Sans `destination-in`, l'ennemi traîne un carré de
     couleur derrière lui. */
  g.globalAlpha=1;
  g.globalCompositeOperation='destination-in';
  g.drawImage(im,sx,sy,sw,sh,0,0,w,h);
  /* Et on REND le contexte à son état neutre : un canevas laissé en
     `destination-in` efface tout ce qu'on y dessinerait au tour suivant. */
  g.globalCompositeOperation='source-over';
  return _teintureCv;
}

