/* ÉTIQUETTE AU-DESSUS, plus aux pieds.

   Les noms étaient écrits sous le sprite (sy+22). En vue isométrique, tout ce
   qui est sous un personnage est recouvert par la tuile de mur suivante dans
   l'ordre de tri : dès qu'un PNJ se tenait devant un mur, son nom disparaissait.
   Au-dessus de la tête, rien ne passe par-dessus.

   Le texte est cerné de noir : lisible sur le Stilmat clair comme sur la roche. */
function etiquette(sx,sy,txt,col,taille){
  if(!txt)return;
  ctx.save();
  ctx.font=(taille||11)+'px Trebuchet MS';ctx.textAlign='center';ctx.textBaseline='alphabetic';
  ctx.lineWidth=3;ctx.strokeStyle='rgba(0,0,0,0.85)';ctx.lineJoin='round';
  ctx.strokeText(txt,sx,sy);
  ctx.fillStyle=col||'#e8ecf6';ctx.fillText(txt,sx,sy);
  ctx.restore();
}
/* LE CHEVRON ET L'ÉTIQUETTE ÉTAIENT ÉCRITS SEPT FOIS.             (Phase 4)

   Sept copies des mêmes trois lignes dans `drawNpc`, qui ne différaient que
   par la teinte, la hauteur et le texte. Changer la pulsation du chevron
   obligeait à la changer sept fois — et il suffisait d'en oublier une pour
   qu'un PNJ batte à contretemps des autres.

   Les écarts réels sont conservés tels quels : le portail d'arène bat plus
   fort (0,35) et plus vite (240 ms) que les autres, et le corps stylisé écrit
   plus petit. Ce sont des choix, pas des oublis — ils deviennent visibles
   maintenant qu'ils sont des arguments au lieu d'être noyés dans la copie. */
const NPC_TEINTE_OR    = '244,211,94';
const NPC_TEINTE_FEU   = '255,120,60';
const NPC_TEINTE_GLACE = '127,208,255';
const NPC_PULSE = 250;     // période de battement du chevron, en ms
function _npcMarqueur(sx, sy, o){
  const gl=0.5+(o.amp||0.3)*Math.sin(performance.now()/(o.periode||NPC_PULSE));
  ctx.fillStyle='rgba('+(o.teinte||NPC_TEINTE_OR)+','+gl+')';
  ctx.font=(o.police||13)+'px Trebuchet MS';ctx.textAlign='center';
  ctx.fillText('▼',sx,sy-o.dyChevron);
  etiquette(sx,sy-o.dyEtiquette,o.texte,o.couleur,o.taille);
  ctx.textAlign='left';
}

function _npcOmbre(sx,sy,oy,rx,ry){
  ctx.fillStyle='rgba(0,0,0,0.38)';ctx.beginPath();ctx.ellipse(sx,sy+oy,rx,ry,0,0,6.28);ctx.fill();
}

/* Trois planches chargées à la demande, une seule fois, rangées sur la
   fonction elle-même. Le motif était recopié trois fois. */
function _npcImage(cle, src){
  if(!drawNpc[cle]){drawNpc[cle]=new Image();drawNpc[cle].src=src;}
  return drawNpc[cle];
}

/* Le libellé du PNJ. Deux variantes, et leurs trois écarts sont VOULUS : la
   version illustrée nomme la salle d'une balise et invite à « Parler » ; le
   corps stylisé se contente de « Balise » et affiche le nom du personnage. */
function _npcLibelle(npc, illustre){
  switch(npc.type){
    case 'smith':       return 'Forgeronne';
    case 'waypoint':    return illustre?(npc.salle||'Balise'):'Balise';
    case 'arenamaster': return 'Anselme';
    case 'arena':       return 'Arène';
    case 'return':      return 'Portail';
    case 'stash':       return 'Coffre';
    case 'quest':       return illustre?t('pnj.parler'):nomPnj(npc);
    default:            return illustre?t('pnj.marchand'):nomPnj(npc);
  }
}

/* Chaque forme rend `true` quand elle a dessiné. Une planche pas encore
   décodée rend `false` et laisse la suivante essayer : le PNJ n'est jamais
   invisible, il retombe au pire sur le corps stylisé. */
function _npcMaitreArene(npc, sx, sy){
  if(npc.type!=='arenamaster'||typeof MISC_ICON==='undefined'||!MISC_ICON.arena_master_sw)return false;
  const mi=_npcImage('_am',MISC_ICON.arena_master_sw);
  if(!(mi.complete&&mi.naturalWidth))return false;
  const DR=128,NF=9;_npcOmbre(sx,sy,DR*0.01,18,7);ctx.imageSmoothingEnabled=false;
  const cw=mi.naturalWidth/NF,fr=Math.floor(performance.now()/180)%NF;
  ctx.drawImage(mi,fr*cw,0,cw,mi.naturalHeight,sx-DR/2,hautSprite(sy,DR,mi,cw,mi.naturalHeight,'n:_am',0.01),DR,DR);
  _npcMarqueur(sx,sy,{dyChevron:84,dyEtiquette:98,texte:'Maître',couleur:'#ffd0a8',teinte:NPC_TEINTE_FEU});
  return true;
}

function _npcPortailArene(npc, sx, sy){
  if(npc.type!=='arena'||typeof MISC_ICON==='undefined'||!MISC_ICON.arena_portal)return false;
  if(npc.vert){sx=npc.tx*TS-cam.x;sy=npc.ty*TS-cam.y;}
  const ai=_npcImage('_ap',MISC_ICON.arena_portal);
  if(!(ai.complete&&ai.naturalWidth))return false;
  // dessiné EXACTEMENT comme un cube de mur (même échelle, même ancrage)
  const DR=(typeof ISO_TW!=='undefined'?ISO_TW:64);ctx.imageSmoothingEnabled=false;
  ctx.drawImage(ai,sx-DR/2,sy-DR*0.75,DR,DR);
  _npcMarqueur(sx,sy,{dyChevron:78,dyEtiquette:92,texte:'Arène',couleur:'#ffd0a8',
                      teinte:NPC_TEINTE_FEU,amp:0.35,periode:240});
  return true;
}

function _npcPortailVille(npc, sx, sy){
  if(npc.type!=='return'||typeof MISC_ICON==='undefined'||!MISC_ICON.portal_town)return false;
  const pi=_npcImage('_pt',MISC_ICON.portal_town);
  if(!(pi.complete&&pi.naturalWidth))return false;
  const DR=64,bob=Math.sin(performance.now()/420)*2;
  _npcOmbre(sx,sy,DR*0.28,15,6);ctx.imageSmoothingEnabled=false;
  ctx.drawImage(pi,sx-DR/2,sy-DR*0.72+bob,DR,DR);
  _npcMarqueur(sx,sy,{dyChevron:60,dyEtiquette:74,texte:'Portail',couleur:'#cfe8ff',teinte:NPC_TEINTE_GLACE});
  return true;
}

/* Le coffre de rangement dessine TOUJOURS : faute de planche, il retombe sur
   l'émoji. C'est la seule forme qui ne peut pas échouer. */
function _npcCoffre(npc, sx, sy){
  if(npc.type!=='stash')return false;
  const im=(typeof CHEST_IMG!=='undefined')&&CHEST_IMG['closed'];
  if(im&&im.complete&&im.naturalWidth){const DR=42;_npcOmbre(sx,sy,DR*0.30,14,5);ctx.imageSmoothingEnabled=false;ctx.drawImage(im,sx-DR/2,sy-DR*0.62,DR,DR);}
  else{ctx.font='30px serif';ctx.textAlign='center';ctx.fillText('🧰',sx,sy+6);ctx.textAlign='left';}
  _npcMarqueur(sx,sy,{dyChevron:54,dyEtiquette:68,texte:'Coffre',couleur:'#f4d35e'});
  return true;
}

/* La planche du PNJ : animée si elle existe, fixe sinon. La fixe respire
   légèrement — sauf les balises, qui sont du mobilier. */
function _npcSprite(npc, sx, sy){
  const _spk=NPC_KEY[npc.name]||(npc.type==='waypoint'?'balise':null);
  const _ani=_spk&&NPC_ANIM_IMG[_spk], _spi=_spk&&NPC_IMG[_spk];
  const DR=128;
  if(_ani&&_ani.complete&&_ani.naturalWidth){
    ctx.imageSmoothingEnabled=false;
    _npcOmbre(sx,sy,DR*0.01,18,7);
    const cw=_ani.naturalWidth/NPC_ANIM_N,fr=Math.floor(performance.now()/180)%NPC_ANIM_N;
    ctx.drawImage(_ani,fr*cw,0,cw,_ani.naturalHeight,sx-DR/2,sy-DR*0.74,DR,DR);
  } else if(_spi&&_spi.complete&&_spi.naturalWidth){
    ctx.imageSmoothingEnabled=false;
    _npcOmbre(sx,sy,DR*0.01,18,7);
    const _bh=DR*(npc.type==='waypoint'?1:(1+0.022*Math.sin(performance.now()/650)));
    ctx.drawImage(_spi,sx-DR/2,sy-_bh*0.74,DR,_bh);
  } else return false;
  _npcMarqueur(sx,sy,{dyChevron:84,dyEtiquette:98,texte:_npcLibelle(npc,true)});
  return true;
}

/* Le repli : un corps géométrique, quand aucune planche n'est disponible. */
function _npcCorpsStylise(npc, sx, sy){
  _npcOmbre(sx,sy,14,13,5);
  ctx.fillStyle=npc.type==='smith'?'#7a4a2a':npc.type==='waypoint'?'#1f6f88':npc.type==='quest'?'#6a4a8a':'#3a5a8a';
  ctx.beginPath();ctx.moveTo(sx-9,sy-4);ctx.lineTo(sx+9,sy-4);ctx.lineTo(sx+7,sy+14);ctx.lineTo(sx-7,sy+14);ctx.closePath();ctx.fill();
  ctx.fillStyle='#c9b28a';ctx.beginPath();ctx.arc(sx,sy-11,6,0,6.28);ctx.fill();
  ctx.font='16px serif';ctx.textAlign='center';ctx.fillText(npc.ico,sx,sy-16);
  _npcMarqueur(sx,sy,{dyChevron:30,dyEtiquette:44,texte:_npcLibelle(npc,false),
                      couleur:'#e8ecf6',taille:10,police:12});
}

function drawNpc(npc){
  const sx=npc.tx*TS+TS/2-cam.x,sy=npc.ty*TS+TS/2-cam.y;
  if(sx<-40||sx>W+40||sy<-40||sy>H+40)return;
  if(_npcMaitreArene(npc,sx,sy))return;
  if(_npcPortailArene(npc,sx,sy))return;
  if(_npcPortailVille(npc,sx,sy))return;
  if(_npcCoffre(npc,sx,sy))return;
  if(_npcSprite(npc,sx,sy))return;
  _npcCorpsStylise(npc,sx,sy);
}
/* CE QUI S'EXÉCUTE AU CHARGEMENT — sorti du premier niveau.

   Le module ne fait plus que DÉCLARER. Ses actions de chargement sont
   appelées par l'entrée, dans l'ordre des préfixes, ce qui rend l'ordre
   d'évaluation des modules INDIFFÉRENT — sans quoi la conversion en
   modules ES les remettrait dans un ordre imprévisible. */
function _demarrer20(){
  /* Le découpage des 155 icônes en canevas a disparu : `iconeObjetStyle` le
     fait au CSS, à l'affichage, sans rien produire au démarrage. Il reste à
     rafraîchir le sac s'il est déjà ouvert quand l'atlas arrive. */
  _itemAtlasImg.onload=function(){
   try{if(document.getElementById('invPanel').style.display==='block')renderInventory();}catch(e){}};
  _itemAtlasImg.src=ITEM_ATLAS_SRC;
  (function(){for(const th in THEME_TEX){const o={};THEMEPAT[th]=o;
    for(const kind of['floor','wall']){const src=THEME_TEX[th][kind];if(!src)continue;
      const im=new Image();im.onload=(function(oo,kk,image){return function(){try{oo[kk]=ctx.createPattern(image,'repeat');}catch(e){}};})(o,kind,im);im.src=src;}}})();
  for(const k in HERO_ATLAS){const im=new Image();im.src=HERO_ATLAS[k];HERO_IMG[k]=im;}
  HERO_ATLAS.Death=DEATH_SRC;HERO_COLS.Death=DEATH_NF;ANIMDEF.Death={fps:9,loop:false};{const _di=new Image();_di.src=DEATH_SRC;HERO_IMG.Death=_di;}
  for(const k in NPC_TEX){const im=new Image();im.src=NPC_TEX[k];NPC_IMG[k]=im;}
  (function(){var st=document.createElement('style');st.textContent='.gi{background-image:url("'+MISC_ICON.gold_coin+'")}';document.head.appendChild(st);})();
  try{[['icoPot','pot_heal'],['icoMana','pot_mana'],['icoShard','res_shard'],['abPotImg','pot_heal'],['abManaImg','pot_mana'],['abPortalImg','scroll_return'],['rIcoPot','pot_heal'],['rIcoMana','pot_mana'],['rIcoFrag','res_shard'],['rIcoScroll','parchemin_identification'],['icoScroll','parchemin_identification']].forEach(a=>{const el=document.getElementById(a[0]);if(el&&MISC_ICON[a[1]])el.src=MISC_ICON[a[1]];});}catch(e){}
}

